def cells(line):
    return [c.strip() for c in line.strip()[1:-1].split(' | ')]


def with_note(prefix, note, cell=1):
    hits = [l for l in lines if l.startswith(prefix)]
    if len(hits) != 1:
        raise SystemExit(f'머리 「{prefix}」 {len(hits)}개')
    c = cells(hits[0])
    c[cell] = c[cell] + ' ' + note
    return ('set_row', prefix, '| ' + ' | '.join(c) + ' |')


